/**
 * Bản chụp TĨNH bảng cau_hinh_danh_muc / cau_hinh_nhom (bộ sinh cũ đã lưu trữ: tools/luu_tru_sinh_du_lieu/cauhinh/).
 * Đổi danh mục thì sửa CSDL rồi sửa tệp này cho khớp sql/htbb.sql (web/tests/cau-hinh-danh-muc-sql.test.ts kiểm).
 * Bản dự phòng của danh mục cấu hình trung tâm: web đọc bảng cau_hinh_danh_muc / cau_hinh_nhom trước
 * (server/utils/cauHinhDanhMucSql.ts), máy chủ game chỉ đọc bảng (com.htbb.cauhinh.DanhMucSql).
 * Hàm kiểm / so sánh thuần: shared/utils/cauHinhTrungTam.ts.
 */

export type KieuTT = 'co' | 'so' | 'chon' | 'chuoi' | 'ds_chuoi' | 'ds_so' | 'ngay' | 'ngay_gio' | 'nhip'
export type BangTT = 'cau_hinh' | 'nap_cau_hinh' | 'env'

export interface KhoaTT {
  khoa: string
  nhom: string
  ten: string
  moTa: string
  kieu: KieuTT
  macDinh: string
  min?: number
  max?: number
  buoc?: number
  luaChon?: [string, string][]
  soPhanTu?: number
  mau?: string
  doDai?: number
  /** Chuẩn hoá chữ hoa trước khi kiểm (mức nhật ký). */
  hoa?: boolean
  /** 'ngay' = áp dụng ≤ 10 giây; 'khoi_dong_lai' = chỉ đổi khi máy chủ khởi động lại. */
  apDung: 'ngay' | 'khoi_dong_lai'
  nhay?: boolean
  khoaProd?: boolean
  chiDoc?: boolean
  bang: BangTT
  dungO: 'server' | 'web' | 'ca_hai'
  nguon: string
  /** Phân loại: vắng = 'chinh' (chỉnh trên web); 'co_dinh' / 'luon_bat' = ẨN, máy thật bỏ qua CSDL (docs/cau-hinh.md). */
  lop?: 'co_dinh' | 'luon_bat'
}

